"""Original optional projects, built from the catalog's existing component skills.
References support shaping, reward-based chaining and enrichment, not these exact protocols.
"""
def extend(D, add):
    by = {s['code']: s for s in D['skills']}
    parts = [by[c] for c in ['OPEN','SHELF','CLOSE','DRINK']]
    steps = {st['id']: dict(st, component=s['code']) for s in parts for st in s['steps']}
    # Comfort with an appliance can be learned independently of the rope action.
    steps['OPEN-1']['deps'] = []
    steps['OPEN-2']['deps'] = [['OPEN-1',3],['PULL-3',3]]
    steps['SHELF-3']['deps'].append(['OPEN-1',3])
    steps['DRINK-1']['deps'] = [['SHELF-3',3]]
    steps['DRINK-2']['deps'].append(['OPEN-3',3])
    steps['CLOSE-3']['deps'].append(['OPEN-1',3])
    project = dict(by['DRINK'], title='Getting a drink from the fridge', sheet='Brainiacs',
        goal='Build a supervised open, retrieve and deliver routine, with a choice of human or dog closure.',
        sources='P05; P11; P20; P22; P25',
        components=[{k:s[k] for k in ['code','title','cue','setup','sources']} for s in parts],
        steps=[steps[i] for i in ['OPEN-1','OPEN-2','OPEN-3','SHELF-1','SHELF-2','SHELF-3','DRINK-1','DRINK-2','CLOSE-1','CLOSE-2','CLOSE-3','DRINK-3','DRINK-4']])
    D['skills'] = [s for s in D['skills'] if s['code'] not in ['OPEN','SHELF','CLOSE','DRINK']] + [project]

    add('NAMEDFIND','Find and deliver a named toy','Brainiacs',
        'Choose a requested familiar toy, search for it nearby, and deliver it gently.',
        'Your two familiar toy labels, then Find',
        'Two large safe toys with established labels; a clear room and accessible floor-level hiding places. This is optional label learning, not an intelligence test.',
        'A07; A08; P20; P32',[
        ('Connect a named choice to delivery','Begin with the two familiar toys visible nearby. Request one label with neutral hands, then use the known give cue when the dog brings it. Reward generously and switch the requested toy across separate easy turns. Do not add hiding yet.', 'Chooses each requested toy and delivers comfortably in two short mixed-order sessions.', 'Return to separate toy-label play or a one-object retrieve if choices look like guessing.'),
        ('Carry the choice a little farther','Keep both toys obvious and equally accessible. Stand one step farther away before requesting a toy. Reward correct selection and a gentle delivery separately if needed. Change only the return distance, keeping your hands and gaze from pointing toward a toy.', 'Maintains comfortable choices and delivery over a short clear return route.', 'Shorten the return route and reward the first step of carrying toward you.'),
        ('Search for one visible toy','Use only one named toy for this step. Let the dog see you place it beyond a wide doorway while it stays visible from the starting point. Give its label and the search invitation, then receive and reward the return.', 'Willingly crosses the nearby open doorway, locates the single toy and returns.', 'Put the toy on the near side of the doorway. Skip this project if brief visual separation worries the dog.'),
        ('Search for a partly concealed toy','With only one toy present, let the dog watch you place it partly behind a broad safe object. Keep the route open and most of the toy visible. Invite the familiar search, then reward the return with food or a game.', 'Finds and returns either toy separately from several easy partly concealed spots.', 'Expose more of the toy and keep the search within a few steps.'),
        ('Bridge a moment out of sight','Place the single toy just behind the same broad object while the dog watches from beside you. Invite a search immediately. Remain available and help by showing more of the toy before searching becomes frantic or discouraging.', 'Comfortably retrieves the single toy from the familiar briefly out-of-view placement.', 'Use partial concealment again. There is no need for a long hidden search or a forced wait.'),
        ('Choose between two visible placements','Return to both toys in full view, now at different easy floor locations. Request each label in a varied order. Alternate their locations so a particular side or doorway does not predict which toy earns a reward.', 'The requested label, rather than location or pointing, usually guides choices in two short sessions.', 'Put both toys closer and revisit mixed-position two-toy choices before adding concealment.'),
        ('Add a little concealment to one choice','Keep one toy fully visible and the other partly behind the familiar object. Request the partly concealed toy on an easy turn, then reset and request the visible one. Exchange their roles rather than repeatedly requesting the hidden object.', 'Can return either requested toy without always choosing the easiest visible object.', 'Expose both toys and reward reliable choices again. Avoid repeated tests after errors.'),
        ('Use two easy search spots','Put each toy partly behind a different broad object with open access and space to turn. Request one familiar label, then invite the search. Stay neutral but help promptly if the dog loses the task; reward each gentle return.', 'Searches the small area and returns the requested toy from either familiar spot.', 'Return to one partly concealed toy and one visible toy, or use a smaller area.'),
        ('Separate placing from requesting','Let a familiar helper place both toys while your dog is comfortably occupied beside you, without restraint. Start with partial visibility again. Request one label without knowing its location if possible; reward the choice and return without steering the search.', 'Comfortably finds the requested toy when your body position does not reveal its location.', 'Have the dog watch placements again. This game need not become a test of unseen hides.'),
        ('Change one search location','Move just one toy to a new obvious accessible floor spot, leaving the other in a familiar place. Request an easy choice first, then the moved toy. Keep all other features unchanged and return to old spots between new placements.', 'Transfers the small search to several nearby safe spots with ordinary comfortable searching.', 'Make the new spot visible, reduce the area, or return to the familiar pair of locations.'),
        ('Build one clear request','Say the chosen toy label before the familiar search invitation, then pause briefly to allow the whole locate-and-return sequence. Keep the extra search or give cue whenever helpful. Fade one prompt at a time and reward the final delivery generously.', 'Finds and delivers either requested toy with little additional prompting in two brief sessions.', 'Restore the helpful component cue or accept a shorter visible-choice game.'),
        ('Finish with a predictable reset','Run one easy requested search, receive the toy, reward, and give a familiar finished cue. Put props away yourself and offer rest or ordinary play. On another day change only one feature, such as the starting point, and keep the first search easy.', 'Enjoys a short complete search-and-deliver game, finishes comfortably and returns willingly another day.', 'Keep the familiar room and easy placements. Stop for guarding, chewing, frustration or separation distress.')
        ], deps=[['TWOOBJECT-3',3],['LOSTTOY-2',3],['GIVE-2',3]], priority='Optional advanced')

    add('SORT','Two-toy tidy-up','Brainiacs',
        'Learn a particular basket for each of two familiar toys, then tidy a small mixed set.',
        'Tidy (with familiar toy and basket cues as needed)',
        'Two broad low baskets, visually distinct large floor markers and two safe toys. No lids, sharp rims, small labels or objects likely to be swallowed.',
        'P11; P20; P21; A07; A08',[
        ('Give the first basket a clear identity','Put one broad basket on a large distinctive floor marker. Use just one familiar toy. Begin with the known short carry and drop into this basket, reward, and reset. Keep the basket still so successful deposits are easy and comfortable.', 'Makes several gentle deposits into this basket without chewing the toy or basket.', 'Use a wider low basket or hold the toy just above the rim again.'),
        ('Add a destination cue','Say a short basket cue before the known deposit. Begin beside the basket and reward inside the destination, then release away. Increase the approach by one small step while leaving the marker and basket in their familiar position.', 'Approaches the familiar marked basket and deposits from a short distance on its cue.', 'Keep the original drop cue and move closer. The basket cue can remain a helpful prompt.'),
        ('Teach the second destination separately','Remove the first basket. Use the second toy and a different basket on its own distinctive marker. Repeat easy deposits with a different destination cue, rewarding promptly. Work separately until this new setup is as comfortable as the original one.', 'Deposits the second toy into its own marked basket comfortably across short sessions.', 'Return to a close drop above the rim and use clearly different large markers.'),
        ('Pair each toy with its basket','In separate short turns, present one toy and only its matching basket. Invite pickup and deposit, then reward. Alternate which pair is practiced first on different occasions. This establishes two predictable routines before asking the dog to choose a destination.', 'Both toy-to-basket routines work from nearby without searching for an absent basket.', 'Practice the less familiar pair alone and shorten the carry.'),
        ('Introduce the unused basket at a distance','Work the first familiar toy-to-basket routine while the other basket is far away. Give the usual destination cue and reward the correct deposit. If the extra basket attracts mistakes, move it farther away rather than blocking or correcting the dog.', 'Completes the first routine comfortably with the other basket present but well separated.', 'Remove the extra basket, regain an easy deposit, then reintroduce it farther away.'),
        ('Practice the other pair with both baskets','Switch to the second toy, keeping its marked basket near and the unused basket well away. Cue the familiar destination and reward. Change which routine you practice across separate turns so neither basket becomes the only place that earns rewards.', 'Can use either familiar routine while the unused basket is also present.', 'Return to each pair separately. Use more space between destinations and shorter carries.'),
        ('Offer an equal-distance destination choice','Place the two marked baskets several steps apart and equally close to the starting point. Offer only one toy. Give its destination cue with neutral hands and gaze. Reward the correct deposit; after a mistake reset to an easier nearby matching basket.', 'Usually selects the cued destination for either toy without pointing or physical steering.', 'Bring the matching basket nearer again and keep the other one farther away.'),
        ('Fade the extra destination prompt','Present one familiar toy and say the tidy cue before the known basket cue. Pause briefly to let the dog begin the familiar route. Reward a correct independent deposit, while continuing to help promptly whenever the choice is uncertain.', 'The toy and tidy invitation begin to predict its usual destination with fewer extra prompts.', 'Keep both destination cues as part of the game; independent sorting is optional.'),
        ('Swap basket locations with their markers','Move each basket together with its own distinctive marker to the opposite side. Start with the toy very close to its matching destination and use its cue. Gradually return to an equal-distance start without pointing to the destination.', 'Can follow each marked destination after a side swap rather than always taking the old route.', 'Use smaller moves, wider separation, or the original positions. Recheck whether side preference explains earlier choices.'),
        ('Pick one toy from the floor','Put just one toy on the clear floor near the starting point instead of handing it over. Invite the familiar pickup and tidy routine, rewarding the correct deposit. Practice either toy separately before putting both toys on the floor together.', 'Picks up either single floor toy and places it in its usual marked basket.', 'Offer the toy from your hand again or place it closer to its basket.'),
        ('Make two separately rewarded deposits','Place the two familiar toys a little apart on the floor. Invite tidying one, reward the deposit, then give a fresh invitation for the remaining toy. Let the dog choose the order; the aim is two correct destinations, not speed.', 'Makes two comfortable, separately rewarded deposits to the corresponding destinations in two short sessions.', 'Put only one toy down at a time and keep extra basket cues.'),
        ('Complete a little tidy-up routine','Use the familiar two-toy layout, invite tidy, and support either order with component cues as needed. Reward each deposit, then give a clear finished cue and put away the props. Keep future variations small; new toys require their own learning.', 'Enjoys the complete two-deposit routine across varied easy basket positions without frantic repetition.', 'Keep a single destination game or explicit basket cues. This is optional discrimination practice, not a measure of intelligence.')
        ], deps=[['BOX-2',3]], priority='Optional advanced')

    add('POST','A two-person delivery round','Brainiacs',
        'Collect a safe message pouch, deliver to a familiar person and return to a starting station.',
        'Post (plus familiar person, give and station cues as needed)',
        'Two trusted willing adults, a large robust safe pouch with no loose ties and a flat non-slip starting mat. Short clear indoor paths; skip for guarding or separation distress.',
        'P11; P20; P21; P32',[
        ('Make a clear delivery station','Place a familiar flat mat near the sender. Invite an easy mat approach, reward, and release. Separately rehearse one comfortable pouch handover to the nearby receiver. Both adults stay quiet and available; no one holds the dog in place.', 'Voluntarily returns to the starting mat and enjoys a nearby pouch handover.', 'Use a floor marker instead of a mat or return to ordinary messenger practice.'),
        ('Collect from a low tray','Put the familiar empty pouch on a broad stable open tray at an easy natural mouth height. Stand beside it and invite the known pickup, then receive and reward. Keep the tray still and avoid any stretching, climbing or paw placement.', 'Picks up the pouch gently from the tray in several easy attempts.', 'Offer the pouch from your hand or lower the tray onto a safe clear floor.'),
        ('Carry from tray to receiver','Position the receiver only a step from the tray. Invite pickup and the known delivery, then let the receiver ask for give and reward. Reset together before another turn. Keep the sender visible and the path unobstructed.', 'Collects from the tray and delivers gently to the nearby receiver.', 'Hand the pouch over at the starting point or bring the receiver closer.'),
        ('Teach the empty return separately','With no pouch present, let the receiver release the dog toward the nearby familiar starting mat. The sender invites the mat approach and rewards there. Both people remain visible, and the dog can opt out rather than being repeatedly called between them.', 'Comfortably returns empty to the sender’s mat on a simple invitation.', 'Place the mat closer or practice its approach with just the sender present.'),
        ('Join handover and return','Begin with a very short pouch delivery. The receiver asks for give, rewards, then invites the familiar empty return. Reward arrival at the mat as well. Keep rewards at both ends while the two actions become a predictable pleasant sequence.', 'Delivers, releases the pouch and returns to the mat willingly in two short sessions.', 'Practice empty returns and deliveries separately. Avoid repeated calling if the dog wants to stay.'),
        ('Add collection at the start','From beside the mat, invite tray pickup, a short delivery, give and the empty return. Use each familiar component cue and reward both the handover and the return. Rehearse just one round before a break rather than building a rapid shuttle.', 'Collects, delivers and returns with the familiar component cues and comfortable movement.', 'Start with the pouch in your hand again or shorten the receiver’s distance.'),
        ('Introduce the round cue','Say “post” once before the familiar pickup invitation. Guide the same easy round with the known component cues and rewards. Across successful turns pause briefly after the round cue, allowing pickup to start without the extra prompt when the dog is ready.', 'The round cue begins to start the familiar collection-and-delivery routine.', 'Keep the pickup cue. Do not repeat the new word or withhold help to force a response.'),
        ('Lengthen one clear route','Move the receiver one step farther away while keeping them visible. Use the easy collection and return pattern, rewarding at both ends. Alternate this slightly longer round with a close one, changing distance without also moving the tray or mat.', 'Completes a short clear delivery route and comfortable empty return without rushing.', 'Bring the receiver closer. Long distances are unnecessary for a satisfying delivery job.'),
        ('Deliver through an open doorway','Put the receiver beside a wide familiar open doorway, still visible. Practice the easy round, then move them just across the threshold on another turn. Keep exits clear, the sender available and the dog’s path away from door swings.', 'Willingly delivers across the open threshold and returns with ordinary relaxed movement.', 'Keep both people in the same room. Skip doorway work for hesitation or separation worry.'),
        ('Handle a small receiver movement','Before starting a round, have the receiver stand a little to one side of the familiar destination. Keep them visible and use the known delivery invitation. Reward the handover and return. Change position only between rounds, never chase a moving recipient.', 'Finds the visible receiver in several nearby positions without dropping or frantic searching.', 'Restore the familiar standing place and shorten the path.'),
        ('Change human roles carefully','Swap sender and receiver while keeping the route short. Begin with isolated pouch handovers and empty mat returns, then join the familiar round again. Keep the mat with the sender so the return destination stays clear when the people change roles.', 'Can enjoy a short delivery round with either familiar adult as receiver.', 'Use the original roles or practice the unfamiliar handover alone. Social choice takes priority over finishing.'),
        ('Finish a purposeful round','Place one light protected note inside the familiar pouch and invite a single easy round. The receiver removes it only after give, rewards, then releases an empty return. Reward at the mat, say finished and remove the pouch and tray yourself.', 'Completes the chosen short collection, handover and return routine with little prompting in two sessions.', 'Keep the pouch empty, retain component cues or use the original one-way messenger game. Inspect props each time and stop for chewing or guarding.')
        ], deps=[['MESSENGER-3',3],['POUCH-3',3],['MAT-2',3]], priority='Optional advanced')
